{
  "name": "yatefca",
  "version": "1.2.0",
  "type": "module",
  "description": "Deterministic, non-LLM session titles from a first message — a tiny library plus a ready-to-use opencode plugin.",
  "author": "jayF0x",
  "license": "MIT",
  "module": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./opencode": {
      "types": "./dist/opencode.d.ts",
      "import": "./dist/opencode.js"
    }
  },
  "files": [
    "dist",
    "CHANGELOG.md"
  ],
  "sideEffects": false,
  "scripts": {
    "build": "bunx --bun vite build --config config/vite.config.ts",
    "dev": "bunx --bun vite build --watch --config config/vite.config.ts",
    "typecheck": "tsc --noEmit",
    "test": "bun test",
    "format": "biome check --write .",
    "format:check": "biome check .",
    "lint": "biome lint ./src",
    "lint:fix": "biome lint --write ./src",
    "npm:deploy": "bash ./scripts/npm/publish-npm.sh",
    "repo:bootstrap": "bash ./scripts/bootstap.sh"
  },
  "dependencies": {
    "yake-ts": "^1.2.4"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": {
      "optional": true
    }
  },
  "devDependencies": {
    "@biomejs/biome": "^2.5.9",
    "@opencode-ai/plugin": "^1.18.18",
    "bun-types": "^1.3.14",
    "taglify": "^1.2.1",
    "typescript": "^5.9.3",
    "vite": "^8.2.1",
    "vite-plugin-dts": "^4.5.4"
  },
  "engines": {
    "node": ">=18"
  },
  "keywords": [
    "yatefca",
    "session-title",
    "session-naming",
    "yake",
    "keyword-extraction",
    "opencode",
    "opencode-plugin",
    "chat-title",
    "typescript",
    "non-llm",
    "deterministic"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/jayf0x/yatefca.git"
  },
  "homepage": "https://github.com/jayf0x/yatefca#readme",
  "bugs": {
    "url": "https://github.com/jayf0x/yatefca/issues"
  }
}
